import React, { useState, useEffect } from 'react';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import ConflictTable from './components/ConflictTable';
import GlobalResourceMonitor from './components/GlobalResourceMonitor'; // New Component
import { 
  PlusCircle, LayoutDashboard, Printer, AlertTriangle, Zap, Activity 
} from 'lucide-react';

function App() {
  const [departments, setDepartments] = useState([
    { 
      id: 1, name: "College of Computer Studies", code: "CCS",
      subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
      proctors: [], rooms: []
    },
    { 
      id: 2, name: "Business Administration", code: "CBA",
      subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
      proctors: [], rooms: []
    }
  ]);

  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  // --- CORE DATA UPDATER ---
  const updateDeptData = (deptId, field, newData) => {
    setDepartments(prev => prev.map(d => d.id === deptId ? { ...d, [field]: newData } : d));
  };

  // --- ADD NEW DEPARTMENT ---
  const addDepartment = () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Department Code:");
    if (name && code) {
      setDepartments([...departments, { 
        id: Date.now(), name, code: code.toUpperCase(),
        subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
        proctors: [], rooms: []
      }]);
    }
  };

  // --- ENGINE: GENERATE & CONFLICT DETECTION ---
  const handleScheduleGenerated = (newAssignments, newDates, deptCode) => {
    const processedNewData = newAssignments.map(session => ({
      ...session,
      id: `${deptCode}-${Date.now()}-${Math.random()}`,
      dept_code: deptCode,
    }));

    setGlobalSchedule(prev => {
      // Remove old records for THIS department before adding new ones
      const otherDepts = prev.filter(item => item.dept_code !== deptCode);
      const combinedList = [...otherDepts, ...processedNewData];

      // Re-run conflict detection across the entire master list
      return combinedList.map(item => {
        const conflict = combinedList.find(target => 
          target.id !== item.id && 
          target.exam_date === item.exam_date &&
          (target.room === item.room || target.proctor === item.proctor) &&
          (item.start_time < target.end_time && item.end_time > target.start_time)
        );
        return { 
          ...item, 
          hasConflict: !!conflict, 
          conflictWith: conflict?.dept_code,
          conflictType: conflict ? (conflict.room === item.room ? 'ROOM' : 'PROCTOR') : null
        };
      });
    });

    // Update global date registry for the calendar
    if (newDates?.length > 0) {
      setAllExamDates(prev => [...new Set([...prev, ...newDates])].sort((a,b) => new Date(a) - new Date(b)));
    }
  };

  const conflictCount = globalSchedule.filter(s => s.hasConflict).length;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      {/* --- TOP NAVIGATION BAR --- */}
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3 text-white font-black uppercase tracking-tighter text-xl">
          <LayoutDashboard size={28} className="text-blue-500" />
          EXAM_FLOW <span className="text-blue-500 italic">PRO</span>
        </div>

        <div className="flex items-center gap-6">
            <div className={`px-5 py-2 rounded-2xl border-2 flex items-center gap-2 text-[10px] font-black uppercase transition-all ${conflictCount > 0 ? 'bg-rose-500/10 border-rose-500/50 text-rose-500' : 'bg-emerald-500/10 border-emerald-500/50 text-emerald-500'}`}>
                <Activity size={14} className={conflictCount > 0 ? 'animate-pulse' : ''} />
                {conflictCount > 0 ? `${conflictCount} Overlaps Found` : 'System Synchronized'}
            </div>
            <button 
              onClick={addDepartment} 
              className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-600/20 active:scale-95 transition-all"
            >
              Add Department
            </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">

        {/* --- SECTION 1: GLOBAL MONITOR & CONFLICTS --- */}
        <div className="grid grid-cols-1 gap-12 mb-16">
          <ConflictTable schedule={globalSchedule} />

          {/* This is the new visible global list section for rooms and proctors */}
          <GlobalResourceMonitor 
            allDepartments={departments} 
            globalSchedule={globalSchedule} 
          />
        </div>

        {/* --- SECTION 2: DEPARTMENT WORKSPACES --- */}
        <div className="space-y-16">
          <div className="flex items-center gap-4 px-6">
            <div className="h-1 flex-1 bg-slate-200 rounded-full"></div>
            <h2 className="text-xs font-black uppercase text-slate-400 tracking-[0.4em]">Department Workspaces</h2>
            <div className="h-1 flex-1 bg-slate-200 rounded-full"></div>
          </div>

          {departments.map((dept) => (
            <DepartmentCard 
              key={dept.id} 
              dept={dept}
              allDepartments={departments}
              onUpdate={(field, data) => updateDeptData(dept.id, field, data)}
              globalSchedule={globalSchedule}
              onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
            />
          ))}
        </div>

        {/* --- SECTION 3: MASTER CALENDAR / EXPORT --- */}
        <div className="mt-32 pt-24 border-t-4 border-slate-900/5">
            <div className="flex justify-between items-end mb-12 px-6">
                <div>
                  <h2 className="text-6xl font-black text-slate-900 tracking-tighter mb-2">Master <span className="text-blue-600 italic">Timeline</span></h2>
                  <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest">Consolidated Institutional Exam Schedule</p>
                </div>
                <button 
                  onClick={() => window.print()} 
                  className="bg-slate-900 hover:bg-slate-800 text-white px-10 py-5 rounded-[2rem] font-black text-[10px] uppercase tracking-widest flex items-center gap-3 shadow-2xl transition-all active:scale-95"
                >
                    <Printer size={20}/> Generate Final PDF Report
                </button>
            </div>

            <div className="bg-white p-4 rounded-[4rem] shadow-xl border border-slate-100">
              {globalSchedule.length > 0 ? (
                <ScheduleCalendar scheduleData={globalSchedule} examDates={allExamDates} />
              ) : (
                <div className="py-32 text-center">
                  <div className="inline-block p-8 rounded-full bg-slate-50 mb-4">
                    <Zap size={48} className="text-slate-200" />
                  </div>
                  <p className="text-slate-300 font-black uppercase tracking-[0.5em] text-sm">System Idle: Generate a schedule to begin</p>
                </div>
              )}
            </div>
        </div>
      </main>

      {/* --- FOOTER STATUS --- */}
      <footer className="fixed bottom-0 w-full bg-white/80 backdrop-blur-md border-t border-slate-100 py-4 px-10 flex justify-between items-center z-40">
        <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest">
          &copy; 2026 EXAM_FLOW PRO &bull; Institutional Resource Management
        </div>
        <div className="flex gap-6">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
            <span className="text-[9px] font-black text-slate-600 uppercase italic">Proctors Live: {departments.reduce((acc, d) => acc + d.proctors.length, 0)}</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-blue-500"></div>
            <span className="text-[9px] font-black text-slate-600 uppercase italic">Active Rooms: {departments.reduce((acc, d) => acc + d.rooms.length, 0)}</span>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;
